import{describe,it,expect,beforeEach,vi}from"vitest";import{AudioGuideSystem}from"../../frontend/js-modules/audio-guide-system.js";describe("AudioGuideSystem",()=>{let e,t;beforeEach(()=>{void 0===globalThis.SpeechSynthesisUtterance&&(globalThis.SpeechSynthesisUtterance=class{constructor(e){this.text=e,this.rate=1,this.lang="en-IN"}}),e={speak:vi.fn(),pause:vi.fn(),resume:vi.fn(),cancel:vi.fn()},t=new AudioGuideSystem({speechSynth:e})}),it("should initialize with default parameters",()=>{expect(t.isPlaying).toBe(!1),expect(t.playbackRate).toBe(1),expect(t.selectedLang).toBe("en-IN")}),it("should retrieve phonetic pronunciations for monuments",()=>{const e=t.getPronunciation("Taj Mahal");expect(e).toEqual({phonetic:"Taaj Muh-hahl",lang:"hi-IN"});const a=t.getPronunciation("Unknown Monument");expect(a).toEqual({phonetic:"Unknown Monument",lang:"en-IN"})}),it("should trigger speech synthesis on speakText",()=>{const a=t.speakText("Welcome to Taj Mahal");expect(a).toBe(!0),expect(e.speak).toHaveBeenCalledOnce()}),it("should adjust playback rate within bounds [0.5, 2.0]",()=>{t.setRate(1.5),expect(t.playbackRate).toBe(1.5),t.setRate(3),expect(t.playbackRate).toBe(2),t.setRate(.1),expect(t.playbackRate).toBe(.5)}),it("should notify subscribers on state changes",()=>{const e=vi.fn();t.subscribe(e),t.speakText("Hampi Guide"),expect(e).toHaveBeenCalled()}),it("should handle pause, resume, and stop operations",()=>{t.isPlaying=!0,t.pause(),expect(e.pause).toHaveBeenCalledOnce(),expect(t.isPaused).toBe(!0),t.resume(),expect(e.resume).toHaveBeenCalledOnce(),t.stop(),expect(e.cancel).toHaveBeenCalledOnce(),expect(t.isPlaying).toBe(!1)})});